-- users/by-email
-- One account by email, for `pnpm users:role` (run on the server only).
--
-- Parameters, with the example values used to render this file:
--   $1 = "someone@example.invalid"
--   $2 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/users.ts. Do not edit by hand.

select "id", "name", "email", "role", "two_factor_enabled"
from "users"
where lower("users"."email") = lower($1)
limit $2;
